-- 57 سؤالاً: كمي 19 + لفظي 38 (منها 17 في قطع استيعاب)
-- آمن لإعادة التشغيل: guard على وجود أسئلة المجموعة
-- ═══════════════════════════════════════════════════════════════
BEGIN;

INSERT INTO leak_groups (id, title, leak_date, section, question_count, description, is_active, accent_color)
VALUES ('ad080926-2026-4c00-9d00-080920260001', 'تسريبات القدرات – الثلاثاء ٨ سبتمبر ٢٠٢٦', '2026-09-08', 'mixed', 57, 'أسئلة اختبار القدرات المحوسب ليوم الثلاثاء ٨ سبتمبر ٢٠٢٦ (٢٦ ربيع الأول ١٤٤٨) — القسمان الكمي واللفظي مع الشروح.', true, '#6D28D9')
ON CONFLICT (id) DO NOTHING;

DO $mig$
BEGIN
IF EXISTS (SELECT 1 FROM questions WHERE leak_group_id = 'ad080926-2026-4c00-9d00-080920260001') THEN
  RAISE NOTICE 'أسئلة المجموعة موجودة مسبقاً — تخطي الإدراج';
ELSE
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'قارن بين:
القيمة الأولى: محيط خماسي منتظم طول ضلعه ١ سم
القيمة الثانية: محيط دائرة طول نصف قطرها ١ سم', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 1, 'محيط الخماسي = ٥ × ١ = ٥ سم، ومحيط الدائرة = ٢π × ١ ≈ ٦٫٢٨ سم؛ فالقيمة الثانية أكبر.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الإحصاء والاحتمالات', 'اختيار من متعدد', 'في رسم بياني للنسب المئوية حسب الفئة العمرية: الفئة ٢٥–٣٤: ذكور ٧٠ وإناث ٣٥؛ الفئة ٣٥–٤٤: ذكور ٥٦ وإناث ٤٠؛ الفئة ٤٥–٥٤: ذكور ٩٨ وإناث ٢٥. كم النسبة المئوية للإناث اللاتي أعمارهن من ٣٥ إلى ٤٤؟', '["٥٦٪", "٤٨٪", "٤٠٪", "٦٠٪"]'::jsonb, 2, 'نقرأ عمود الإناث في الفئة ٣٥–٤٤ مباشرة من الرسم: ٤٠٪.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الإحصاء والاحتمالات', 'اختيار من متعدد', 'يبيّن التمثيل عدد الطلاب الحاصلين على كل درجة: الدرجة ١: ٣ طلاب، ٢: ٤، ٣: ٣، ٤: ٦، ٥: ٥، ٦: ٢، ٧: ٣. ما الدرجة التي حصل عليها أكبر عدد من الطلاب؟', '["٣", "٤", "٥", "٦"]'::jsonb, 1, 'أكبر عدد من الطلاب هو ٦، وهو عند الدرجة ٤.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الجبر', 'اختيار من متعدد', 'إذا كان ك × ل × م × ن = صفر، و ل × م × ن × و = ١، فإن .....', '["ل = صفر", "م = صفر", "ك = صفر", "ن = صفر"]'::jsonb, 2, 'من المعادلة الثانية لا يمكن أن يكون أي من ل أو م أو ن صفرًا (وإلا لصار الناتج صفرًا لا ١)، فالصفر في المعادلة الأولى لا بد أن يأتي من ك.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'في الشكل المجاور مستقيمان متوازيان بينهما مثلث، الزاوية الخارجية عند رأسه الواقع على المستقيم العلوي ١١٠°، وزاويته الداخلية الأخرى ٥٠°. أوجد قيمة ص (زاويته عند الرأس الواقع على المستقيم السفلي).', '["٥٠", "٧٠", "٦٠", "١١٠"]'::jsonb, 2, 'الزاوية الداخلية عند الرأس العلوي = ١٨٠ − ١١٠ = ٧٠°، ومجموع زوايا المثلث ١٨٠: ص = ١٨٠ − ٧٠ − ٥٠ = ٦٠°.', 'https://czzcmbxejxbotjemyuqf.supabase.co/storage/v1/object/public/question-figures/qudurat_sep08_q005_parallel.png', 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', '٦٢٫٥٪ من ١٦٠ = .....', '["٤٠", "٦٠", "٨٠", "١٠٠"]'::jsonb, 3, '٦٢٫٥٪ = ٥/٨، و(٥/٨) × ١٦٠ = ١٠٠.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'في مثلث قائم الزاوية إحدى زاويتيه الحادتين ٤٠°، وس هي الزاوية الخارجية عند رأس الزاوية الحادة الأخرى. قارن بين:
القيمة الأولى: ١٣٠°
القيمة الثانية: س', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 2, 'الزاوية الخارجية للمثلث تساوي مجموع الزاويتين الداخليتين البعيدتين عنها: س = ٩٠ + ٤٠ = ١٣٠°؛ فالقيمتان متساويتان.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'في مثلث زاويتان قياس كل منهما ٥٥°، وس هي الزاوية الخارجية عند الرأس الثالث. أوجد قياس س.', '["١٠٠", "١١٠", "١٢٠", "١٣٠"]'::jsonb, 1, 'الزاوية الخارجية = مجموع الزاويتين الداخليتين البعيدتين = ٥٥ + ٥٥ = ١١٠°.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'أوجد أربعة أمثال نصف العدد ٢.', '["٢", "٤", "٨", "١٦"]'::jsonb, 1, 'نصف العدد ٢ = ١، وأربعة أمثاله = ٤.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الجبر', 'اختيار من متعدد', 'احسب قيمة: ٢¹¹ − ٢¹⁰', '["١", "١١", "٢¹⁰", "١١٠"]'::jsonb, 2, '٢¹¹ = ٢ × ٢¹⁰، فالفرق = ٢ × ٢¹⁰ − ٢¹⁰ = ٢¹⁰.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'شركة عدد موظفيها ٤٢٠، منهم ١٤٠ سعوديًا والباقي من جنسيات أخرى. إذا أرادت الشركة رفع نسبة السعوديين إلى ٥٠٪ عن طريق استبدال بعض الموظفين من الجنسيات الأخرى بسعوديين، فكم سعوديًا توظف؟', '["٧٠", "٧٥", "٨٠", "٨٥"]'::jsonb, 0, '٥٠٪ من ٤٢٠ = ٢١٠ سعوديًا مطلوبًا، والموجود ١٤٠، فتوظف ٢١٠ − ١٤٠ = ٧٠.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'متوازي أضلاع محيطه ٢٠ سم، وطول أحد ضلعيه ٦ سم. أوجد طول الضلع الآخر س.', '["٢", "٣", "٤", "٦"]'::jsonb, 2, 'محيط متوازي الأضلاع = ٢ × (س + ٦) = ٢٠، فـس + ٦ = ١٠ ومنها س = ٤ سم.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'إذا كان ٥² و٧² من عوامل العدد ٣¹³ × ٧ × س، فما أصغر قيمة ممكنة لـس؟', '["١٤٥", "١٥٦", "١٧٥", "١٩٠"]'::jsonb, 2, 'العدد يحوي عاملًا واحدًا من ٧ فيحتاج ٧ أخرى من س، ولا يحوي أي ٥ فيحتاج ٥² من س؛ أصغر س = ٥² × ٧ = ١٧٥.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'مقياس الرسم في خريطة ١ : ٥٠٠٠٠٠٠. إذا كانت المسافة بين مدينتين على الخريطة ١٦ سم، فأوجد المسافة الحقيقية بينهما بالكيلومتر.', '["٨٠٠", "٨٨٠", "٩٠٠", "٩٦٠"]'::jsonb, 0, 'المسافة الحقيقية = ١٦ × ٥٠٠٠٠٠٠ = ٨٠٠٠٠٠٠٠ سم، وبالقسمة على ١٠٠٠٠٠ (عدد السنتيمترات في الكيلومتر) = ٨٠٠ كم.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الجبر', 'اختيار من متعدد', 'قارن بين:
القيمة الأولى: (٠٫٢٥)³ − (٠٫٢٥)⁴
القيمة الثانية: (٠٫٢٥)⁴ − (٠٫٢٥)³', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 0, 'العدد بين ٠ و١ تصغر قيمته كلما زاد أسّه، فـ(٠٫٢٥)³ أكبر من (٠٫٢٥)⁴. إذًا القيمة الأولى موجبة والثانية سالبة (نفس الفرق بإشارة معكوسة)؛ فالأولى أكبر.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'اشترى رجل مجموعة من الألعاب، كل لعبتين بـ٢٫٥ ريال، وباع اللعبة الواحدة بـ٢٫٥ ريال. إذا كان قد اشترى بـ٢٥ ريالًا، فكم لعبة اشترى؟', '["١٠", "١٥", "٢٠", "٢٥"]'::jsonb, 2, '٢٥ ÷ ٢٫٥ = ١٠ مجموعات، وكل مجموعة لعبتان، فعدد الألعاب = ٢٠.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الحساب', 'اختيار من متعدد', 'سيارة تقطع ٧٢ كم في ٣٢ دقيقة. كم كيلومترًا تقطع في الساعة بالسرعة نفسها؟', '["١٣٠", "١٣٥", "١٤٠", "١٥٠"]'::jsonb, 1, 'في الدقيقة الواحدة تقطع ٧٢ ÷ ٣٢ = ٢٫٢٥ كم، وفي ٦٠ دقيقة: ٢٫٢٥ × ٦٠ = ١٣٥ كم.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'دائرة مساحتها ٩٠π ظُلّل معظمها وبقي قطاع غير مظلل زاويته المركزية ٣٦°. قارن بين:
القيمة الأولى: مساحة الجزء غير المظلل
القيمة الثانية: ٩π', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 2, 'مساحة القطاع = (٣٦ ÷ ٣٦٠) × ٩٠π = (١/١٠) × ٩٠π = ٩π؛ فالقيمتان متساويتان.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('quant', NULL, 'الهندسة', 'اختيار من متعدد', 'مثلث أ ب ج قائم الزاوية في ج، قياس الزاوية أ = ٦٠°. النقطة د على الوتر أ ب بحيث تكون الزاوية د ج ب = ٦٠°. قارن بين:
القيمة الأولى: ج د
القيمة الثانية: ج ب', '["القيمة الأولى أكبر", "القيمة الثانية أكبر", "القيمتان متساويتان", "المعطيات غير كافية"]'::jsonb, 1, 'الزاوية ب = ٣٠°. في المثلث د ج ب: زاوية ج = ٦٠ وزاوية ب = ٣٠ فزاوية د = ٩٠°، أي أن ج د عمودي على أ ب، وهو المقابل لزاوية ٣٠° فيساوي نصف ج ب؛ فـج ب أكبر.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'التناظر اللفظي', 'اختيار من متعدد', 'جذور : شجرة', '["سواري : أعلام", "قواعد : أبنية", "أغصان : أوراق", "بحر : أمواج"]'::jsonb, 1, 'الجذور هي الأساس الذي تقوم عليه الشجرة، والقواعد هي الأساس الذي تقوم عليه الأبنية: علاقة أساس وما يقوم عليه.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'التناظر اللفظي', 'اختيار من متعدد', 'دراسة : تخرج', '["مشي : وصول", "سابق : لاحق", "سفر : عبور", "هدف : غاية"]'::jsonb, 0, 'التخرج هو ما تنتهي إليه الدراسة، والوصول هو ما ينتهي إليه المشي: علاقة عمل وغايته التي ينتهي إليها.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'التناظر اللفظي', 'اختيار من متعدد', 'إهمال : إخفاق', '["هدية : محبة", "شك : يقين", "جد : كسل", "نوم : يقظة"]'::jsonb, 0, 'الإهمال سبب يؤدي إلى الإخفاق، والهدية سبب يؤدي إلى المحبة: علاقة سبب ونتيجة؛ أما بقية الخيارات فأضداد.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'التناظر اللفظي', 'اختيار من متعدد', 'المال : الولد', '["الذهب : التجارة", "القلب : الشعور", "الكحل : العطر", "الماء : الحياة"]'::jsonb, 2, 'المال والولد يقترنان في كونهما زينة الحياة الدنيا، والكحل والعطر يقترنان في كونهما زينة أيضًا: علاقة اقتران في صنف واحد.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'إكمال الجملة', 'اختيار من متعدد', 'السعادة ينبوع ....... الجميع أن يصلوا إليه، وهم لا ....... أنه تحت أقدامهم.', '["يفكر – يتمثلون", "يتمنى – يعلمون", "يسعى – يسمعون", "يكاد – يؤمنون"]'::jsonb, 1, 'الجميع يتمنون الوصول إلى السعادة وهم لا يعلمون أنها قريبة منهم؛ فالزوج المستقيم: يتمنى – يعلمون.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'إكمال الجملة', 'اختيار من متعدد', 'من أيقن بـ....... جاد بـ.......', '["نفسه – روحه", "يمينه – يساره", "موته – أبنائه", "الخلف – العطية"]'::jsonb, 3, 'الحكمة المعروفة: من أيقن بالخَلَف (أن الله يعوّضه) جاد بالعطية؛ فالإكمال الوحيد المستقيم: الخلف – العطية.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
