  VALUES ('verbal', NULL, 'إكمال الجملة', 'اختيار من متعدد', 'لا فائدة من الدنيا ....... إذا كان حذاؤك .......', '["الواسعة – ضيقًا", "الضيقة – مناسبًا", "الصغيرة – واسعًا", "الفارغة – واسعًا"]'::jsonb, 0, 'المعنى: سعة الدنيا لا تنفع من كان حذاؤه ضيقًا يؤلمه؛ فالتقابل المقصود: الواسعة – ضيقًا.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'إكمال الجملة', 'اختيار من متعدد', 'يجب أن يكون توخي الحذر ....... في البيئات .......', '["رئيسًا – المتعاملة", "مطلوبًا – الفوضوية", "ثانويًا – الإنشائية", "ممنوعًا – الهادئة"]'::jsonb, 1, 'الحذر يكون مطلوبًا في البيئات الفوضوية التي تكثر فيها المخاطر؛ فالزوج المناسب: مطلوبًا – الفوضوية.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
