  VALUES ('verbal', NULL, 'إكمال الجملة', 'اختيار من متعدد', 'يكون الإنسان نبيلًا إذا زادت صفة ....... عنده على باقي الصفات؛ لأنه يفضّل ....... على نفسه.', '["الإيثار – غيره", "الصبر – غيره", "الكرم – ماله", "الصدق – نفسه"]'::jsonb, 0, 'تفضيل الغير على النفس هو تعريف الإيثار نفسه؛ فالزوج المناسب: الإيثار – غيره.', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
