  VALUES ('verbal', NULL, 'الخطأ السياقي', 'اختيار من متعدد', 'الطبيب يستخدم الليزر في العمليات الجراحية التي تتطلب وقتًا دقيقًا.', '["الطبيب", "الليزر", "وقتًا", "دقيقًا"]'::jsonb, 2, 'الدقة المطلوبة في الجراحة تكون في العمل لا في الوقت؛ فالخطأ في «وقتًا» وصوابها «عملًا».', NULL, 'ad080926-2026-4c00-9d00-080920260001', NULL, NULL, NULL, 'active', false);
