  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'حسب النص، ما آخر خطوة في إدارة الوقت؟', '["تنظيم الوقت", "ترتيب الوقت", "تخطيط الوقت", "تنسيق الوقت"]'::jsonb, 0, 'النص صريح: تنظيم الوقت يلي مرحلتي تخطيط الوقت وتنسيقه، فهو آخر الخطوات.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90801-2026-4c00-9d00-000000000001', 'تنظيم الوقت هو مرحلة من مراحل إدارة الوقت، وهو يلي مرحلة تخطيط الوقت وتنسيق الوقت، ويشمل تحديد الأهداف ويتنبأ بالوقت المناسب. وإدارة الوقت هي عملية تنظيم وتخطيط كيفية توزيع وقتك بين المهام والأنشطة المختلفة. وفي أغلب الأحيان من يفشل في إدارة وقته يفشل في حياته. والصندوق عند تنظيمه يمكنه استيعاب العديد من الأشياء، وكذلك الوقت يشبه الصندوق.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'العنوان الأعم للقطعة:', '["تنظيم الوقت", "إدارة الوقت", "ترتيب الوقت", "تنسيق الوقت"]'::jsonb, 1, 'تنظيم الوقت وتخطيطه وتنسيقه كلها مراحل تندرج تحت إدارة الوقت، فهي العنوان الأعم.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90801-2026-4c00-9d00-000000000001', 'تنظيم الوقت هو مرحلة من مراحل إدارة الوقت، وهو يلي مرحلة تخطيط الوقت وتنسيق الوقت، ويشمل تحديد الأهداف ويتنبأ بالوقت المناسب. وإدارة الوقت هي عملية تنظيم وتخطيط كيفية توزيع وقتك بين المهام والأنشطة المختلفة. وفي أغلب الأحيان من يفشل في إدارة وقته يفشل في حياته. والصندوق عند تنظيمه يمكنه استيعاب العديد من الأشياء، وكذلك الوقت يشبه الصندوق.', 2, 'active', false);
