  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'حسب النص، ما العلاقة بين (يفشل في حياته) و(يفشل في إدارة وقته)؟', '["نتيجة لسبب", "سبب لنتيجة", "طردية", "عكسية"]'::jsonb, 0, 'الفشل في الحياة نتيجة، والفشل في إدارة الوقت سببها؛ فالأولى نتيجة للثانية.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90801-2026-4c00-9d00-000000000001', 'تنظيم الوقت هو مرحلة من مراحل إدارة الوقت، وهو يلي مرحلة تخطيط الوقت وتنسيق الوقت، ويشمل تحديد الأهداف ويتنبأ بالوقت المناسب. وإدارة الوقت هي عملية تنظيم وتخطيط كيفية توزيع وقتك بين المهام والأنشطة المختلفة. وفي أغلب الأحيان من يفشل في إدارة وقته يفشل في حياته. والصندوق عند تنظيمه يمكنه استيعاب العديد من الأشياء، وكذلك الوقت يشبه الصندوق.', 3, 'active', false);
