  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'حسب النص، ما معنى (يتنبأ)؟', '["يحدد", "يُقدّر", "يعرف", "يخطط"]'::jsonb, 1, 'التنبؤ بالوقت المناسب هو تقديره قبل حدوثه؛ فالمعنى الأقرب «يُقدّر».', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90801-2026-4c00-9d00-000000000001', 'تنظيم الوقت هو مرحلة من مراحل إدارة الوقت، وهو يلي مرحلة تخطيط الوقت وتنسيق الوقت، ويشمل تحديد الأهداف ويتنبأ بالوقت المناسب. وإدارة الوقت هي عملية تنظيم وتخطيط كيفية توزيع وقتك بين المهام والأنشطة المختلفة. وفي أغلب الأحيان من يفشل في إدارة وقته يفشل في حياته. والصندوق عند تنظيمه يمكنه استيعاب العديد من الأشياء، وكذلك الوقت يشبه الصندوق.', 4, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'أي الآتي يتفق مع النص؟', '["الفاشل ينجح في تنظيم وقته", "الناجح لا يفشل أبدًا", "النجاح في الحياة يتبع النجاح في إدارة الوقت", "الفشل في تخطيط الوقت لا يؤثر في الحياة"]'::jsonb, 2, 'النص يربط الفشل في الحياة بالفشل في إدارة الوقت، وبالمقابل يكون النجاح في الحياة تابعًا للنجاح في إدارة الوقت.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90801-2026-4c00-9d00-000000000001', 'تنظيم الوقت هو مرحلة من مراحل إدارة الوقت، وهو يلي مرحلة تخطيط الوقت وتنسيق الوقت، ويشمل تحديد الأهداف ويتنبأ بالوقت المناسب. وإدارة الوقت هي عملية تنظيم وتخطيط كيفية توزيع وقتك بين المهام والأنشطة المختلفة. وفي أغلب الأحيان من يفشل في إدارة وقته يفشل في حياته. والصندوق عند تنظيمه يمكنه استيعاب العديد من الأشياء، وكذلك الوقت يشبه الصندوق.', 5, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'يُفهم من النص أن:', '["الاهتمام بالوقت أمر ثانوي", "شُبّه الوقت بالصندوق لضيقه", "تنظيم الوقت يُنجز الأعمال", "الوقت لا يمكن تنظيمه"]'::jsonb, 2, 'تشبيه الوقت بالصندوق الذي يتسع للعديد من الأشياء عند تنظيمه يدل على أن تنظيم الوقت يتيح إنجاز أعمال أكثر.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90801-2026-4c00-9d00-000000000001', 'تنظيم الوقت هو مرحلة من مراحل إدارة الوقت، وهو يلي مرحلة تخطيط الوقت وتنسيق الوقت، ويشمل تحديد الأهداف ويتنبأ بالوقت المناسب. وإدارة الوقت هي عملية تنظيم وتخطيط كيفية توزيع وقتك بين المهام والأنشطة المختلفة. وفي أغلب الأحيان من يفشل في إدارة وقته يفشل في حياته. والصندوق عند تنظيمه يمكنه استيعاب العديد من الأشياء، وكذلك الوقت يشبه الصندوق.', 6, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'لماذا يقصد الشعراء النابغة الذبياني؟', '["طلبًا للشهرة", "طلبًا للرزق", "لينتقد شعرهم", "لتخليد أسمائهم"]'::jsonb, 2, 'النص صريح: كان الشعراء يقصدونه من كل مكان ليعرضوا عليه شعرهم، أي ليحكم عليه وينتقده.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90802-2026-4c00-9d00-000000000002', 'زياد بن معاوية بن ضباب الذبياني المعروف بالنابغة الذبياني، كان النابغة تُضرب له قبة حمراء من أدم في سوق عكاظ، وكان عندما يلقي شعرًا يحضره كثير من الناس، فيقصده الشعراء من كل مكان ليعرضوا عليه شعرهم. وقد أصبح نابغة بعدما أصبح رجلًا، ولُقب بهذا اللقب لأنه نبغ في الشعر، أي أبدع في الشعر دفعة واحدة.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'علاقة جملة (لأنه نبغ في الشعر) بما قبلها:', '["تعليل", "سبب", "تفصيل", "إجمال"]'::jsonb, 0, 'الجملة تبدأ بـ«لأنه» وتبيّن علة تلقيبه بالنابغة، فهي تعليل لما قبلها.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90802-2026-4c00-9d00-000000000002', 'زياد بن معاوية بن ضباب الذبياني المعروف بالنابغة الذبياني، كان النابغة تُضرب له قبة حمراء من أدم في سوق عكاظ، وكان عندما يلقي شعرًا يحضره كثير من الناس، فيقصده الشعراء من كل مكان ليعرضوا عليه شعرهم. وقد أصبح نابغة بعدما أصبح رجلًا، ولُقب بهذا اللقب لأنه نبغ في الشعر، أي أبدع في الشعر دفعة واحدة.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'يُستنتج من النص أن النبوغ يُقاس بـ:', '["الجاه", "المكانة", "الموهبة", "السن"]'::jsonb, 2, 'سُمّي نابغة لأنه أبدع في الشعر دفعة واحدة، فمقياس النبوغ في النص هو الموهبة والإبداع لا السن أو الجاه.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90802-2026-4c00-9d00-000000000002', 'زياد بن معاوية بن ضباب الذبياني المعروف بالنابغة الذبياني، كان النابغة تُضرب له قبة حمراء من أدم في سوق عكاظ، وكان عندما يلقي شعرًا يحضره كثير من الناس، فيقصده الشعراء من كل مكان ليعرضوا عليه شعرهم. وقد أصبح نابغة بعدما أصبح رجلًا، ولُقب بهذا اللقب لأنه نبغ في الشعر، أي أبدع في الشعر دفعة واحدة.', 3, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'يدل النص على:', '["قلة الشعراء", "كثرة الشعراء", "تباين الشعراء في العصر الجاهلي", "تشابه الشعراء في العصر الجاهلي"]'::jsonb, 2, 'وجود شاعر يُحكَّم بين الشعراء ويقصدونه لعرض شعرهم يدل على تفاوت مستوياتهم وتباينهم.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90802-2026-4c00-9d00-000000000002', 'زياد بن معاوية بن ضباب الذبياني المعروف بالنابغة الذبياني، كان النابغة تُضرب له قبة حمراء من أدم في سوق عكاظ، وكان عندما يلقي شعرًا يحضره كثير من الناس، فيقصده الشعراء من كل مكان ليعرضوا عليه شعرهم. وقد أصبح نابغة بعدما أصبح رجلًا، ولُقب بهذا اللقب لأنه نبغ في الشعر، أي أبدع في الشعر دفعة واحدة.', 4, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'الضمير في كلمة (فيقصده) يعود على:', '["النابغة", "السوق", "الناس", "الشعر"]'::jsonb, 0, 'الشعراء يقصدون النابغة نفسه ليعرضوا عليه شعرهم، فالهاء تعود عليه.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90802-2026-4c00-9d00-000000000002', 'زياد بن معاوية بن ضباب الذبياني المعروف بالنابغة الذبياني، كان النابغة تُضرب له قبة حمراء من أدم في سوق عكاظ، وكان عندما يلقي شعرًا يحضره كثير من الناس، فيقصده الشعراء من كل مكان ليعرضوا عليه شعرهم. وقد أصبح نابغة بعدما أصبح رجلًا، ولُقب بهذا اللقب لأنه نبغ في الشعر، أي أبدع في الشعر دفعة واحدة.', 5, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'العنوان المناسب للنص:', '["أهمية الري", "أنظمة الري", "تكلفة أنظمة الري", "مشكلة الري"]'::jsonb, 1, 'النص يعرّف أنظمة الري الحديثة ويعدد طرقها ومن يلجأ إليها، فمحوره أنظمة الري.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90803-2026-4c00-9d00-000000000003', 'أنظمة الري الحديثة هي تلك الأنظمة التي تُستخدم في ري الأراضي بالمناطق الصحراوية، وهذه الأراضي عادةً ما تكون رملية، كما أنها غالبًا ما تكون غير مستوية السطح. وهناك عدة طرق للري الحديث، منها الري باستخدام الرشاشات، والري بالتنقيط، والري السطحي. وعادةً ما تلجأ الدول الفقيرة في الموارد المائية إلى الاعتماد على طرق الري الحديثة لافتقارها لمصدر دائم للمياه العذبة.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'معنى (تفتقر) في النص:', '["تغنى", "تتردد", "تحتاج", "تفلس"]'::jsonb, 2, '«لافتقارها لمصدر دائم للمياه» أي لحاجتها إليه وعدم وجوده عندها؛ فمعنى تفتقر: تحتاج.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90803-2026-4c00-9d00-000000000003', 'أنظمة الري الحديثة هي تلك الأنظمة التي تُستخدم في ري الأراضي بالمناطق الصحراوية، وهذه الأراضي عادةً ما تكون رملية، كما أنها غالبًا ما تكون غير مستوية السطح. وهناك عدة طرق للري الحديث، منها الري باستخدام الرشاشات، والري بالتنقيط، والري السطحي. وعادةً ما تلجأ الدول الفقيرة في الموارد المائية إلى الاعتماد على طرق الري الحديثة لافتقارها لمصدر دائم للمياه العذبة.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'ذُكر في النص عدة طرق لأنظمة الري الحديثة، كان عددها:', '["١", "٢", "٣", "٤"]'::jsonb, 2, 'الطرق المذكورة: الري بالرشاشات، والري بالتنقيط، والري السطحي — ثلاث طرق.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90803-2026-4c00-9d00-000000000003', 'أنظمة الري الحديثة هي تلك الأنظمة التي تُستخدم في ري الأراضي بالمناطق الصحراوية، وهذه الأراضي عادةً ما تكون رملية، كما أنها غالبًا ما تكون غير مستوية السطح. وهناك عدة طرق للري الحديث، منها الري باستخدام الرشاشات، والري بالتنقيط، والري السطحي. وعادةً ما تلجأ الدول الفقيرة في الموارد المائية إلى الاعتماد على طرق الري الحديثة لافتقارها لمصدر دائم للمياه العذبة.', 3, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'يعود الضمير (الهاء) في (سلطانها) الثانية على:', '["الأندلس", "غرناطة", "جبل طارق", "تلمسان"]'::jsonb, 3, 'الجملة: «ثم تلمسان فأكرمه سلطانها»، فالهاء تعود على أقرب مذكور وهو تلمسان.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90804-2026-4c00-9d00-000000000004', 'محمد بن عبد الله الأندلسي الشهير بلسان الدين بن الخطيب، وُلد في غرناطة سنة ٧١٣هـ، واستوزره سلطانها يوسف بن إسماعيل ثم ابنه الغني بالله، فعظمت مكانته مما دفع حسّاده إلى الوشاية به، فترك الأندلس خلسة إلى جبل طارق ثم تلمسان فأكرمه سلطانها، ولكنه بعد ذلك سُجن وقُتل. ترك ابن الخطيب آثارًا متعددة، فمن مؤلفاته: الإحاطة في أخبار غرناطة، واللمحة البدرية في الدولة النصرية، وأعمال الأعلام فيمن بويع قبل الاحتلام من ملوك الإسلام، وأوصاف الناس في التواريخ.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'يُفهم من النص أن لسان الدين بن الخطيب وُلد في:', '["الربع الأول من القرن السابع", "الثلث الثاني من القرن السابع", "الربع الأول من القرن الثامن", "الثلث الثاني من القرن الثامن"]'::jsonb, 2, 'سنة ٧١٣هـ تقع في القرن الثامن الهجري (٧٠١–٨٠٠)، وفي ربعه الأول (٧٠١–٧٢٥).', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90804-2026-4c00-9d00-000000000004', 'محمد بن عبد الله الأندلسي الشهير بلسان الدين بن الخطيب، وُلد في غرناطة سنة ٧١٣هـ، واستوزره سلطانها يوسف بن إسماعيل ثم ابنه الغني بالله، فعظمت مكانته مما دفع حسّاده إلى الوشاية به، فترك الأندلس خلسة إلى جبل طارق ثم تلمسان فأكرمه سلطانها، ولكنه بعد ذلك سُجن وقُتل. ترك ابن الخطيب آثارًا متعددة، فمن مؤلفاته: الإحاطة في أخبار غرناطة، واللمحة البدرية في الدولة النصرية، وأعمال الأعلام فيمن بويع قبل الاحتلام من ملوك الإسلام، وأوصاف الناس في التواريخ.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'نفهم من النص أن لسان الدين بن الخطيب كان:', '["أديبًا ومؤرخًا", "أديبًا وكاتبًا", "وزيرًا ومؤرخًا", "وزيرًا ورئيسًا"]'::jsonb, 2, 'استوزره السلطان (فهو وزير)، ومؤلفاته في أخبار غرناطة والدولة النصرية والتواريخ تدل على أنه مؤرخ.', NULL, 'ad080926-2026-4c00-9d00-080920260001', 'e1a90804-2026-4c00-9d00-000000000004', 'محمد بن عبد الله الأندلسي الشهير بلسان الدين بن الخطيب، وُلد في غرناطة سنة ٧١٣هـ، واستوزره سلطانها يوسف بن إسماعيل ثم ابنه الغني بالله، فعظمت مكانته مما دفع حسّاده إلى الوشاية به، فترك الأندلس خلسة إلى جبل طارق ثم تلمسان فأكرمه سلطانها، ولكنه بعد ذلك سُجن وقُتل. ترك ابن الخطيب آثارًا متعددة، فمن مؤلفاته: الإحاطة في أخبار غرناطة، واللمحة البدرية في الدولة النصرية، وأعمال الأعلام فيمن بويع قبل الاحتلام من ملوك الإسلام، وأوصاف الناس في التواريخ.', 3, 'active', false);
END IF;
END
